import Foundation

/// A bundled, versioned slice of UNC Charlotte's catalog for one program: the program, its technical-elective list
/// (catalog vs DegreeWorks), and every course those electives need, recursively (code, title, credits, requirement
/// text and its parsed groups). Generated by tools/catalog/refresh_catalog.py (scripts/refresh_catalog.sh) from
/// catalog.charlotte.edu; read-only data.
public struct CatalogDataset: Codable, Hashable, Sendable {
    public struct TechElectiveRule: Codable, Hashable, Sendable {
        public var label: String
        /// Classes required (4).
        public var count: Int
        /// Credit hours required (12).
        public var credits: Double
        /// At least this many must be MEGR (3).
        public var minimumMEGR: Int
        /// The catalog's sentence ("Select four of the following. At least three of the four must be MEGR courses.").
        public var rule: String
        /// The DegreeWorks wording, for reference.
        public var degreeWorks: String?
    }

    public struct Program: Codable, Hashable, Sendable {
        public var id: String
        public var name: String
        public var catalogTitle: String?
        public var school: String
        public var catalogYear: String
        public var catalogURL: String
        public var techElectives: TechElectiveRule
        /// Codes of the program's required courses (common first year + additional math / physics + major courses).
        public var core: [String]
    }

    public struct Elective: Codable, Hashable, Sendable, Identifiable {
        public var code: String
        /// Listed by the catalog's program page.
        public var inCatalog: Bool
        /// Listed by the DegreeWorks audit's Technical Elective block.
        public var inDegreeWorks: Bool
        public var megr: Bool
        /// The catalog's condition, e.g. MEGR 3221 "may count as a Technical Elective only if MEGR 3216 is completed…".
        public var condition: String?
        /// The course page exists in this catalog year.
        public var existsInCatalog: Bool

        public var id: String { code }
    }

    public struct Course: Codable, Hashable, Sendable, Identifiable {
        public var code: String
        public var title: String
        public var credits: Double?
        public var creditsText: String?
        public var description: String?
        public var prereqText: String?
        public var coreqText: String?
        public var preOrCoreqText: String?
        public var restriction: String?
        public var catalogURL: String?
        public var coid: String?
        /// AND of OR-groups: must be done in an EARLIER term.
        public var prereqGroups: [[String]]
        /// Must be taken in the same term (the app's corequisites allow earlier too).
        public var coreqGroups: [[String]]
        /// "Pre- or corequisite": same term or earlier — the app's corequisites.
        public var preOrCoreqGroups: [[String]]
        /// Non-course conditions: restrictions, grades, permission, asides.
        public var notes: [String]
        /// A required course of the program.
        public var core: Bool
        /// Set when the page came from a later catalog (the course has no page in the program's catalog year).
        public var catalogYear: String?

        public var id: String { code }

        /// Corequisites in the app's sense (same term or earlier): strict corequisites + pre-or-corequisites.
        public var sameTermGroups: [[String]] { coreqGroups + preOrCoreqGroups }

        public init(code: String, title: String, credits: Double? = 3, prereqGroups: [[String]] = [], coreqGroups: [[String]] = [],
                    preOrCoreqGroups: [[String]] = [], notes: [String] = [], core: Bool = false, prereqText: String? = nil,
                    catalogURL: String? = nil) {
            self.code = code
            self.title = title
            self.credits = credits
            self.prereqGroups = prereqGroups
            self.coreqGroups = coreqGroups
            self.preOrCoreqGroups = preOrCoreqGroups
            self.notes = notes
            self.core = core
            self.prereqText = prereqText
            self.catalogURL = catalogURL
        }

        enum CodingKeys: String, CodingKey {
            case code, title, credits, creditsText, description, prereqText, coreqText, preOrCoreqText, restriction, catalogURL, coid
            case prereqGroups, coreqGroups, preOrCoreqGroups, notes, core, catalogYear
        }

        public init(from decoder: Decoder) throws {
            let c = try decoder.container(keyedBy: CodingKeys.self)
            code = CourseCode.normalize(try c.decode(String.self, forKey: .code))
            title = (try? c.decodeIfPresent(String.self, forKey: .title)) ?? ""
            credits = try? c.decodeIfPresent(Double.self, forKey: .credits)
            creditsText = try? c.decodeIfPresent(String.self, forKey: .creditsText)
            description = try? c.decodeIfPresent(String.self, forKey: .description)
            prereqText = try? c.decodeIfPresent(String.self, forKey: .prereqText)
            coreqText = try? c.decodeIfPresent(String.self, forKey: .coreqText)
            preOrCoreqText = try? c.decodeIfPresent(String.self, forKey: .preOrCoreqText)
            restriction = try? c.decodeIfPresent(String.self, forKey: .restriction)
            catalogURL = try? c.decodeIfPresent(String.self, forKey: .catalogURL)
            coid = try? c.decodeIfPresent(String.self, forKey: .coid)
            prereqGroups = ((try? c.decodeIfPresent([[String]].self, forKey: .prereqGroups)) ?? nil) ?? []
            coreqGroups = ((try? c.decodeIfPresent([[String]].self, forKey: .coreqGroups)) ?? nil) ?? []
            preOrCoreqGroups = ((try? c.decodeIfPresent([[String]].self, forKey: .preOrCoreqGroups)) ?? nil) ?? []
            notes = ((try? c.decodeIfPresent([String].self, forKey: .notes)) ?? nil) ?? []
            core = ((try? c.decodeIfPresent(Bool.self, forKey: .core)) ?? nil) ?? false
            catalogYear = (try? c.decodeIfPresent(String.self, forKey: .catalogYear)) ?? nil
        }
    }

    public var version: Int
    public var generatedAt: String?
    public var program: Program
    public var sources: [String]
    public var electives: [Elective]
    /// Codes named by the DegreeWorks list or a requirement that have no page in this catalog year.
    public var missingFromCatalog: [String]
    /// The later catalog consulted for codes missing from the program's year ("2026-2027").
    public var nextCatalogYear: String?
    /// Normalized code → course.
    public var courses: [String: Course]

    public init(version: Int = 1, generatedAt: String? = nil, program: Program, sources: [String] = [], electives: [Elective],
                missingFromCatalog: [String] = [], courses: [String: Course]) {
        self.version = version
        self.generatedAt = generatedAt
        self.program = program
        self.sources = sources
        self.electives = electives
        self.missingFromCatalog = missingFromCatalog
        self.courses = courses
    }

    /// The course with `code` (case / space-insensitive, equivalents tried too).
    public func course(_ code: String) -> Course? {
        for candidate in CourseCode.equivalentCodes(code) {
            if let hit = courses[candidate] { return hit }
        }
        return nil
    }

    /// The bundled UNC Charlotte BSME 2025-2026 dataset (Resources/uncc-bsme-2025-26.json).
    public static let bsme2025: CatalogDataset? = {
        guard let url = Bundle.module.url(forResource: "uncc-bsme-2025-26", withExtension: "json"),
              let data = try? Data(contentsOf: url) else { return nil }
        return try? JSONDecoder().decode(CatalogDataset.self, from: data)
    }()

    /// Decodes a dataset file.
    public static func load(_ data: Data) throws -> CatalogDataset {
        try JSONDecoder().decode(CatalogDataset.self, from: data)
    }
}
